package main

import (
	"context"
	"fmt"

	"google.golang.org/api/drive/v3"
	"google.golang.org/api/option"
)

// DriveItem represents a file or folder in Google Drive.
type DriveItem struct {
	ID       string
	Name     string
	IsFolder bool
	Size     int64 // bytes; 0 for folders
}

func driveService(ctx context.Context) (*drive.Service, error) {
	client, err := driveClient(ctx)
	if err != nil {
		return nil, err
	}
	return drive.NewService(ctx, option.WithHTTPClient(client))
}

// DriveFindFolder returns the ID of the first folder named name within parentID.
// Use "root" for the Drive root. Folder names with single quotes are not supported.
func DriveFindFolder(ctx context.Context, parentID, name string) (string, error) {
	svc, err := driveService(ctx)
	if err != nil {
		return "", err
	}
	q := fmt.Sprintf(
		"name = '%s' and mimeType = 'application/vnd.google-apps.folder' and '%s' in parents and trashed = false",
		name, parentID,
	)
	result, err := svc.Files.List().Q(q).Fields("files(id, name)").Do()
	if err != nil {
		return "", fmt.Errorf("find folder %q: %w", name, err)
	}
	if len(result.Files) == 0 {
		return "", fmt.Errorf("folder %q not found in parent %q", name, parentID)
	}
	return result.Files[0].Id, nil
}

// DriveListFolder returns the direct children of the folder with the given ID,
// folders first then files, both sorted by name.
// Note: results are capped at 100 items (Drive API default page size).
func DriveListFolder(ctx context.Context, folderID string) ([]DriveItem, error) {
	svc, err := driveService(ctx)
	if err != nil {
		return nil, err
	}
	q := fmt.Sprintf("'%s' in parents and trashed = false", folderID)
	result, err := svc.Files.List().
		Q(q).
		Fields("files(id, name, mimeType, size)").
		OrderBy("folder,name").
		Do()
	if err != nil {
		return nil, fmt.Errorf("list folder %q: %w", folderID, err)
	}
	items := make([]DriveItem, len(result.Files))
	for i, f := range result.Files {
		items[i] = DriveItem{
			ID:       f.Id,
			Name:     f.Name,
			IsFolder: f.MimeType == "application/vnd.google-apps.folder",
			Size:     f.Size,
		}
	}
	return items, nil
}

package main

import (
	"context"
	"fmt"
	"os"
	"path/filepath"

	"google.golang.org/api/drive/v3"
)

// DriveUploadFile uploads the local file at localPath to the Drive folder with
// the given ID. The filename on Drive matches the base name of localPath.
// Returns the ID of the created Drive file.
func DriveUploadFile(ctx context.Context, localPath, driveFolderID string) (string, error) {
	f, err := os.Open(localPath)
	if err != nil {
		return "", fmt.Errorf("open %s: %w", localPath, err)
	}
	defer f.Close()

	svc, err := driveService(ctx)
	if err != nil {
		return "", err
	}

	meta := &drive.File{
		Name:    filepath.Base(localPath),
		Parents: []string{driveFolderID},
	}
	created, err := svc.Files.Create(meta).Media(f).Fields("id, name, size").Do()
	if err != nil {
		return "", fmt.Errorf("upload %s: %w", localPath, err)
	}
	return created.Id, nil
}

package main

import (
	"embed"

	"github.com/wailsapp/wails/v2"
	"github.com/wailsapp/wails/v2/pkg/options"
	"github.com/wailsapp/wails/v2/pkg/options/assetserver"
)

//go:embed all:frontend/dist
var assets embed.FS

func main() {
	// Create an instance of the app structure
	app := NewApp()

	// Create application with options
	err := wails.Run(&options.App{
		Title:  "paper-scan-processor",
		Width:  1024,
		Height: 768,
		AssetServer: &assetserver.Options{
			Assets: assets,
		},
		BackgroundColour: &options.RGBA{R: 27, G: 38, B: 54, A: 1},
		OnStartup:        app.startup,
		Bind: []interface{}{
			app,
		},
	})

	if err != nil {
		println("Error:", err.Error())
	}
}

import { useRef, useEffect } from 'react'
import { TransformWrapper, TransformComponent, ReactZoomPanPinchRef } from 'react-zoom-pan-pinch'
import { Center, Loader } from '@mantine/core'
import * as pageCache from '../lib/pageCache'

const DETAIL_WIDTH = 1400

interface Props {
  pdfPath: string
  pageNum: number
  pageCount: number
  rotation?: number
  onToggleSkip?: () => void
  onRotate?: () => void
}

export default function DetailPanel({ pdfPath, pageNum, pageCount, rotation = 0, onToggleSkip, onRotate }: Props) {
  pageCache.usePageCacheRender()
  const transformRef = useRef<ReactZoomPanPinchRef>(null)

  useEffect(() => {
    pageCache.load(pdfPath, pageNum, DETAIL_WIDTH)
    if (pageNum > 1) pageCache.load(pdfPath, pageNum - 1, DETAIL_WIDTH) // prefetch previous page
    if (pageNum < pageCount) pageCache.load(pdfPath, pageNum + 1, DETAIL_WIDTH) // prefetch next page
  }, [pdfPath, pageNum, pageCount])

  useEffect(() => {
    transformRef.current?.resetTransform()
  }, [pageNum, rotation])

  useEffect(() => {
    const handler = (e: KeyboardEvent) => {
      if (e.target instanceof HTMLInputElement || e.target instanceof HTMLTextAreaElement) return
      if (e.key === 'r') {
        e.preventDefault()
        onRotate?.()
      }
    }
    window.addEventListener('keydown', handler)
    return () => window.removeEventListener('keydown', handler)
  }, [onRotate])

  const cachedWidth = pageCache.getCachedWidth(pdfPath, pageNum)
  const src = cachedWidth !== undefined && cachedWidth >= DETAIL_WIDTH
    ? pageCache.getSrc(pdfPath, pageNum)
    : undefined

  return (
    <div
      style={{
        flex: 1,
        height: '100%',
        overflow: 'hidden',
        position: 'relative',
        background: 'var(--mantine-color-gray-1)',
        padding: 8,
      }}
    >
      {pageCache.isLoading(pdfPath, pageNum) && (
        <Center style={{ position: 'absolute', inset: 0, zIndex: 1 }}>
          <Loader />
        </Center>
      )}
      {src && (
        <TransformWrapper ref={transformRef} centerOnInit minScale={0.1} maxScale={8}>
          <TransformComponent
            wrapperStyle={{ width: '100%', height: '100%' }}
            contentStyle={{ display: 'flex', alignItems: 'center', justifyContent: 'center' }}
          >
            <img
              src={src}
              alt={`Page ${pageNum}`}
              draggable={false}
              style={{ maxWidth: '100%', maxHeight: '100%', display: 'block', userSelect: 'none', transform: rotation ? `rotate(${rotation}deg)` : undefined }}
            />
          </TransformComponent>
        </TransformWrapper>
      )}
    </div>
  )
}

import { useEffect, useState } from 'react'
import { RenderPage } from '../../wailsjs/go/main/App'

interface Entry { src: string; width: number }

// entries stores the best (highest-width) image loaded so far per page.
// loading tracks the width of the currently in-flight render per page; a higher-res
// request overwrites the value, which lets the stale lower-res .then know it was superseded.
// failed tracks the highest width that failed per page; retries at higher widths are still allowed.
const entries = new Map<string, Entry>()
const loading = new Map<string, number>()
const failed = new Map<string, number>()
const listeners = new Set<() => void>()

const pageKey = (path: string, page: number) => `${path}\0${page}`

function notify() {
  for (const fn of listeners) fn()
}

export function subscribe(fn: () => void): () => void {
  listeners.add(fn)
  return () => listeners.delete(fn)
}

export function usePageCacheRender() {
  const [, setTick] = useState(0)
  useEffect(() => subscribe(() => setTick(t => t + 1)), [])
}

export function getSrc(path: string, page: number): string | undefined {
  return entries.get(pageKey(path, page))?.src
}

export function getCachedWidth(path: string, page: number): number | undefined {
  return entries.get(pageKey(path, page))?.width
}

export function isLoading(path: string, page: number): boolean {
  return loading.has(pageKey(path, page))
}

export function isFailed(path: string, page: number): boolean {
  return failed.has(pageKey(path, page))
}

export function load(path: string, page: number, width: number): void {
  if (!path) return
  const k = pageKey(path, page)
  const existing = entries.get(k)
  if (existing && existing.width >= width) return
  const currentlyLoading = loading.get(k)
  // Don't start a new render if a higher-res one is already in-flight — it will supersede this one.
  if (currentlyLoading !== undefined && currentlyLoading >= width) return
  const failedAt = failed.get(k)
  if (failedAt !== undefined && failedAt >= width) return
  // Overwrite any lower-res in-flight entry. The superseded render will still complete but its
  // .then/.catch checks loading.get(k) === width before mutating state, so it becomes a no-op.
  loading.set(k, width)
  RenderPage(path, page, Math.round(width * window.devicePixelRatio))
    .then((b64) => {
      // A higher-res render may have completed while this one was in-flight — don't downgrade.
      const current = entries.get(k)
      if (!current || current.width <= width) {
        entries.set(k, { src: `data:image/png;base64,${b64}`, width })
      }
      // Only clear loading if we're still the active render (not superseded by a higher-res one).
      if (loading.get(k) === width) loading.delete(k)
      notify()
    })
    .catch(() => {
      if (loading.get(k) === width) {
        loading.delete(k)
        failed.set(k, width)
      }
      notify()
    })
}

export function evict(path: string): void {
  const prefix = path + '\0'
  for (const k of entries.keys()) if (k.startsWith(prefix)) entries.delete(k)
  for (const k of loading.keys()) if (k.startsWith(prefix)) loading.delete(k)
  for (const k of failed.keys()) if (k.startsWith(prefix)) failed.delete(k)
  notify()
}

